import{_ as e,o as t,c as p,O as l}from"./chunks/framework.ac0f74f3.js";const r="/assets/zh-ygda.8ed55601.png",_=JSON.parse('{"title":"员工档案","description":"","frontmatter":{},"headers":[],"relativePath":"综合管理/员工档案.md","filePath":"综合管理/员工档案.md"}'),o={name:"综合管理/员工档案.md"};function i(n,a,s,d,h,c){return t(),p("div",null,[...a[0]||(a[0]=[l('<h1 id="员工档案" tabindex="-1">员工档案 <a class="header-anchor" href="#员工档案" aria-label="Permalink to &quot;员工档案&quot;">​</a></h1><blockquote><p>员工档案列表位于综合部，可编辑、批量导入员工信息、批量导出员工信息，表头设置信息，员工档案和基础设置-人员信息数据同步。（以基础设置-人员信息中的数据为准，同步至员工档案）</p></blockquote><h4 id="_1-编辑功能" tabindex="-1">1.编辑功能 <a class="header-anchor" href="#_1-编辑功能" aria-label="Permalink to &quot;1.编辑功能&quot;">​</a></h4><ul><li><p>在编辑之前所创建的员工建档(置灰的代表不可更改)</p><p>-支持修改手机号，但不会更新到基础设置-员工信息中，需要通知运营管理员进行信息同步</p><p>-输入身份证号后，自动计算性别，出生日期，年龄</p></li><li><p>是否在职</p><p>-是的情况下是代表在职，否的情况下是代表离职（此地方不可编辑，是从基础信息-员工权限页面中同步过来的，是否在职取决于员工权限页面的启用/停用）</p></li></ul><h4 id="_2-表头设置" tabindex="-1">2.表头设置 <a class="header-anchor" href="#_2-表头设置" aria-label="Permalink to &quot;2.表头设置&quot;">​</a></h4><ul><li>点击表头设置按钮设置列表表头的标题是否显示</li></ul><h4 id="_3-批量导入" tabindex="-1">3.批量导入 <a class="header-anchor" href="#_3-批量导入" aria-label="Permalink to &quot;3.批量导入&quot;">​</a></h4><ul><li><p>使用下载的模版，可直接进行员工档案信息批量导入，对于已存在的数据，重复导入时，进行补全信息</p><p>-例如：人员张三已存在，只填写了姓名，手机号，使用模版填写了专业，专长，再次导入时会将缺少的信息进行补全。\\</p><p>-1.点击批量导入，先下载模板（注意下载的模板只适用于批量导入员工档案列表里面上传的模板)</p><p>-2.点开下载的模板进行编辑（编辑时请阅读表格上面的提示文案，以防导入时出现错误，从而无法导入）</p><p>-3.点击或者拖拽所保存的模板（只有在员工档案列表的批量导入中下载的模板才能上传，其他无效）进行上传</p><p>-4.上传成功会弹出显示上传的数据，可选择性导入或者一键导入（如果无法导入，请滑动到页面最后，查看提示信息，可能存在编辑时出现的错误，需从新更改再次上传）</p></li></ul><h4 id="_4-批量导出" tabindex="-1">4.批量导出 <a class="header-anchor" href="#_4-批量导出" aria-label="Permalink to &quot;4.批量导出&quot;">​</a></h4><p>-点击导出按钮</p><p>-勾选需要导出的信息</p><p>-也可手动输入需导出N条信息进行导出</p><p>-再次点击导出按钮导出</p><p><img src="'+r+'" alt="如图所示"></p>',14)])])}const m=e(o,[["render",i]]);export{_ as __pageData,m as default};
